#!/usr/bin/env python3
import json, os, shutil, sys

MAX_PER_DIR = 30
MAX_FILE_SIZE = 15 * 1024 * 1024
DIGITS = "123456789ABCDEFGHIJLMNPQRSTUVWXY"

def to_base30(n):
    if n == 0:
        return DIGITS[0]
    out = []
    while n:
        n, r = divmod(n, MAX_PER_DIR)
        out.append(DIGITS[r])
    return "".join(reversed(out))

def main():
    if len(sys.argv) != 3:
        sys.exit("usage: python compress.py <input_dir> <output_dir>")
    inp, out = sys.argv[1], sys.argv[2]
    os.makedirs(out, exist_ok=True)

    files = []
    for root, dirs, names in os.walk(inp):
        for name in sorted(names):
            path = os.path.join(root, name)
            files.append(os.path.relpath(path, inp))
    files.sort()

    for i, rel in enumerate(files):
        top, sub = divmod(i, MAX_PER_DIR)
        destdir = os.path.join(out, to_base30(top), to_base30(sub))
        os.makedirs(destdir, exist_ok=True)
        dest = os.path.join(destdir, os.path.basename(rel))
        size = os.path.getsize(rel and os.path.join(inp, rel))
        if size > MAX_FILE_SIZE:
            sys.exit("file too large to reshard: %s" % rel)
        if os.path.abspath(os.path.join(inp, rel)) != os.path.abspath(dest):
            shutil.copy2(os.path.join(inp, rel), dest)

    manifest = [{"original": r, "resharded": os.path.join(to_base30(t), to_base30(s), os.path.basename(r))}
                for i, r in enumerate(files) for (t, s) in [divmod(i, MAX_PER_DIR)]]
    with open(os.path.join(out, "manifest.json"), "w") as f:
        json.dump(manifest, f, indent=1)

if __name__ == "__main__":
    main()
